TLM.f("Tempora/Adv3-5",{"officium":"Feria VI Quattuor Temporum in Adventu","rule":["Oratio Dominica","no Gloria","no Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"ruleInherited":["no Gloria","Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"fallback":"Tempora/Adv3-0","from":{"GradualeF":"Tempora/Adv3-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:151-152"},{"k":"text","la":"Prope es tu, Dómine, et omnes viæ tuæ véritas: inítio cognóvi de testimóniis tuis, quia in ætérnum tu es."},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beati immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Prope es tu, Dómine, et omnes viæ tuæ véritas: inítio cognóvi de testimóniis tuis, quia in ætérnum tu es."}],"Oratio":[{"k":"text","la":"Excita, quǽsumus, Dómine, poténtiam tuam, et veni: ut hi, qui in tua pietáte confídunt, ab omni cítius adversitáte liberéntur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 11:1-5"},{"k":"text","la":"Hæc dicit Dóminus Deus: Egrediétur virga de radíce Jesse, et flos de radíce ejus ascéndet. Et requiéscet super eum spíritus Dómini: spíritus sapiéntiæ et intelléctus, spíritus consílii et fortitúdinis, spíritus sciéntiæ et pietátis; et replébit eum spíritus timóris Dómini. Non secundum visiónem oculórum judicábit: neque secúndum audítum áurium árguet: sed judicábit in justítia páuperes, et árguet in æquitáte pro mansuétis terræ: et percútiet terram virga oris sui, et spíritu labiórum suórum interfíciet ímpium. Et erit justítia cíngulum lumbórum ejus: et fides cinctórium renum ejus."}],"Graduale":[{"k":"ref","la":"Ps 84:8; 84:2"},{"k":"text","la":"Osténde nobis, Dómine, misericórdiam tuam: et salutáre tuum da nobis."},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 79:2; 79:3; 79:2"},{"k":"text","la":"Qui sedes, Dómine, super Chérubim, éxcita poténtiam tuam, et veni."},{"k":"text","la":"Qui regis Israël, inténde: qui dedúcis, velut ovem, Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:39-47"},{"k":"text","la":"In illo témpore: Exsúrgens María ábiit in montána cum festinatióne in civitátem Juda: et intrávit in domum Zacharíæ et salutávit Elísabeth. Et factum est, ut audivit salutatiónem Maríæ Elísabeth, exsultávit infans in útero ejus: et repléta est Spíritu Sancto Elísabeth, et exclamávit voce magna et dixit: Benedícta tu inter mulíeres, et benedíctus fructus ventris tui. Et unde hoc mihi, ut véniat Mater Dómini mei ad me? Ecce enim, ut facta est vox salutatiónis tuæ in áuribus meis, exsultávit in gáudio infans in útero meo. Et beáta, quæ credidísti, quóniam perficiéntur ea, quæ dicta sunt tibi a Dómino. Et ait María: Magníficat ánima mea Dóminum: et exsultávit spíritus meus in Deo, salutári meo."}],"Offertorium":[{"k":"ref","la":"Ps 84:7-8"},{"k":"text","la":"Deus, tu convérsus vivificábis nos, et plebs tua lætábitur in te: osténde nobis, Dómine, misericórdiam tuam, et salutáre tuum da nobis."}],"Secreta":[{"k":"text","la":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Zach 14:5"},{"k":"text","la":"Ecce, Dóminus véniet et omnes Sancti ejus cum eo: et erit in die illa lux magna."}],"Postcommunio":[{"k":"text","la":"Tui nos, Dómine, sacraménti libátio sancta restáuret: et a vetustáte purgátos, in mystérii salutáris fáciat transíre consórtium."},{"k":"macro","name":"Per Dominum"}]},"hr":{"59ed7b0b61d4826e":{"t":"Ps 118, 151-152, Ps 118, 1\n(Ps 118, 151-152) Blizu si, Gospodine, i svi su putovi tvoji istiniti. Već sam davno spoznao iz objave tvoje da si vječan. (Ps 118, 1) Blago onima koji idu neokaljanim putem, koji žive po zakonu Gospodnjem.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 151-152) Blizu si, Gospodine, i svi su putovi tvoji istiniti. Već sam davno spoznao iz objave tvoje da si vječan.","kn":"(Ps. 118, 151-152). Blizu si, Gospodine, i svi su tvoji putovi istina. Od početka sam spoznao o. Tvojim svjedočanstvima, da si vječain (Fs. 118, 1). Blago onima, koji si^ čista života,, koji žive po zakonu Gospodnjem! Slava Ocu. Blizu si . . .","knRef":"Kniewald 1942, str. 44–45 (snimka 23) (OCR)"},"eef105e7a306341e":{"t":"<i>Pomolimo se</i>.\nPokreni, molimo, Gospodine, svoju silu i dođi da što prije oslobodiš od svake protivštine one koji se uzdaju u tvoju dobrotu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"b611644f5b2f334d":{"t":"Isai 11, 1-5\nČitanje Izaije proroka. Ovo govori Gospodin Bog: Iz korijena će Jesejeva izrasti mladica i niknuti cvijet. Na njemu će počivati duh Gospodnji: duh mudrosti i razuma, duh savjeta i jakosti, duh znanja i pobožnosti, i ispunit će ga duh straha Božjega. Neće suditi po oku, niti će karati po onom što čuje, nego će siromasima suditi po pravdi i karat će po pravici za dobro krotkih na zemlji. Šibom svojih riječi udarit će zemlju, a bezbožnika će pogubiti dahom svojih usta. Pravda će opasivati njegove bokove, a vjera će biti njegov pojas.","kn":"Čitanje Izaije proroka. (Iz. 11, 1-5). Ovo govori Gospodin Bog: Izaći će mladica iz stabla . Jese, i cvijet iz korijena njegova procvjetat će. 1 na njemu 00 počivati duh Gospodnji: duh mudrosti, i razuma, duh savjeta, i jakosti, duh znanja i pobožnosti: i napunit će ga duh straha Gospodnjega,. Ne će suditi po viđenju očiju; niti će ipo čuvenju ušiju karati; nego će po pravdi suditi siromasima, 1 po pravici karat će za dobro krotkih na zemlji: i udarit će zemlju šibom usta svojih, i duhom usana svojih pogubit će. bezbožnika. I bit ča pravda pojas oko bokova njegovih: i vjera povez na bedrima njegovim.","knRef":"Kniewald 1942, str. 44–45 (snimka 23) (OCR)"},"793e742d08b8cc88":{"t":"Ps 84, 8 i 2\nPokaži nam, Gospodine, milosrđe svoje i spasenje svoje daj nam. Blagoslovio si, Gospodine, svoju zemlju, izveo si Jakova iz ropstva."},"3677f7a70c26e6e3":{"t":"Lk 1, 39-47\nSlijedi sveto Evanđelje po Luki. U ono vrijeme Marija žurno pođe u planinski kraj u grad Judin, uđe u kuću Zaharije i pozdravi Elizabetu. Kad je Elizabeta čula Marijin pozdrav, zaigra dijete pod njezinim srcem, pa nadahnuta Duhom Svetim klikne jakim glasom: Blagoslovljena ti među ženama, i blagoslovljen plod utrobe tvoje! Tko sam ja da majka mojega Gospodina dolazi k meni? I eto. čim sam čula tvoj pozdrav, od radosti dijete zaigra u meni. Blago tebi, jer si povjerovala, da će se ispuniti što ti je rekao Gospodin. Marija na to reče: Veliča duša moja Gospodina i raduje se duh moj u Bogu spasu mojemu!","kn":"t Slijedi sv. evanđelje po Luki (1, 39-47). U ono vrijeme ustade Marija i pođe žurno u gore, u grad Judin. Uđe u Zaharijinu kuću i pozdravi Elizabetu. Kad je Elizabeta čula Marijin pozdrav, zaigra dijete u njoj. I napuni se Elizabeta duha Svetoga i usklikne jakim glasom: Blagoslovljena ti među ženama i blagoslovljen plod utrobe tvoje! Otkuda meni to, da k meni dolazi majka mojega Gospodina? Jer evO', čim sam čula tvoj pozdrav, zaigralo je dijele u meni. Blago tebi, što si vjerovala, jer će se ispuniti, što ti je rekao Gospodin. Marija nato Kvairena subota u doSašfu reče: Neka veliča moja duša Gospodina, i raduje se moj duh u Bogu, mojemu Spasitelju.","knRef":"Kniewald 1942, str. 44–45 (snimka 23) (OCR)"},"9251242752ac94bf":{"t":"Ps 84, 7-8\nBože, obazri se na nas i oživi nas, i tvoj će se puk veseliti u tebi. Pokaži nam, Gospodine, milosrđe svoje i spasenje svoje daj nam.","kn":"(Ps. 84, 7, 8). Bože, obrati se k nama i oživi nas, da se puk Tvoj raduje u Tebi. Pokaži nam. Gospodine, svoje milosrđe i daj nam svoje spasenje.","knRef":"Kniewald 1942, str. 40–41 (snimka 21) (OCR)"},"0741f87b36183013":{"t":"Primi, molimo, Gospodine, naše darove i molitve te nas nebeskim otajstvima očisti i milostivo usliši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, naše darove i molitve, te nas blago usliši i očisti nebeskim otajstvima, Po . G. n.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"f636106f1b63b827":{"t":"Zah 14, 5-6\nEvo će Gospodin doći i svi sveti njegovi s njime, i bit će u onaj dan svjetlo veliko.","kn":"(Zaih. 14, 5-6). Evo, Gospodin će doći i svi sveti njegovi s njime, i bit će u onaj dan svjetlost velika. ^ _ .","knRef":"Kniewald 1942, str. 46–47 (snimka 24) (OCR)"},"567df46b5c5d48e8":{"t":"<i>Pomolimo se</i>.\nSveto žrtvovanje tvojeg otajstva, Gospodine, neka nas obnovi, da očišćeni od starih mana zavrijedimo dobiti dio u tajni spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"popričesna. Sveto nas, Gospodine, prinošenje Tvoje tajne obnovilo i očišćene od starine prevelo u sudioništvo spasonosnog otajstva, po G. n. I. K.","knRef":"Kniewald 1942, str. 46–47 (snimka 24) (OCR)"}}});
